  let out=replaceOnce(input,"const VERSION='1.3.0-tgctl-p0-consume';","const VERSION='1.4.0-imotion-safe-deploy';",'bridge_version');
  out=replaceOnce(out,"const TGCTL_DIR='/run/prhm-tgctl-approval';","const TGCTL_DIR='/run/prhm-tgctl-approval';\n"+BRIDGE_CONSTANTS,'bridge_constants');
  out=replaceOnce(out,'const server=',''+BRIDGE_FUNCTIONS+'\nconst server=','bridge_functions');
  const routeAnchor="        if(\n          req.method==='POST' &&\n          u.pathname==='/v1/tgctl/authorize'";
  out=replaceOnce(out,routeAnchor,BRIDGE_ROUTES+routeAnchor,'bridge_routes');
